for (const [b, z] of Object.entries(M)) if (z.length < 6) z[5] = BETRIEB_SPALTE[b] ?? 0;
// KYC/KYB: Spalte „compliance“ (7.) – Compliance schreiben, Cockpit/Nutzer/Protokoll lesen, Aufgaben schreiben
