7206:declare const Factory: react.ForwardRefExoticComponent<Omit<LucideProps, "ref"> & react.RefAttributes<SVGSVGElement>>;
13147:declare const Network: react.ForwardRefExoticComponent<Omit<LucideProps, "ref"> & react.RefAttributes<SVGSVGElement>>;
17047:declare const Sprout: react.ForwardRefExoticComponent<Omit<LucideProps, "ref"> & react.RefAttributes<SVGSVGElement>>;

/**
 * Für Portalseiten: Nutzer oder Weiterleitung zum Login.
 * rollen: mindestens eine davon (admin darf immer), sonst 404 (keine Existenz verraten).
 */
export async function portalNutzer({ rollen, admin } = {}) {
  const u = await aktuellerNutzer();
  if (!u) redirect(`/login?weiter=${encodeURIComponent(await aktuellerPfad())}`);
  // Pflicht-2FA noch nicht eingerichtet → nur die Sicherheitsseite
  if (u.zweiFaktorPflichtOffen && !(await aktuellerPfad()).startsWith("/portal/sicherheit")) redirect("/portal/sicherheit?pflicht=1");
  const istAdmin = u.rollen.includes("admin");
  if (admin && !istAdmin) notFound();
  if (admin && istAdmin && !seitenRechtOk(u, await aktuellerPfad())) notFound(); // Bereich ohne Leserecht der Unterrolle
  if (rollen && !istAdmin && !rollen.some((r) => u.rollen.includes(r))) notFound();
  return u;
}

export const istAdmin = (u) => !!u?.rollen?.includes("admin");
export const hatRolle = (u, ...rollen) => istAdmin(u) || rollen.some((r) => u?.rollen?.includes(r));

/** Backend-Aufruf in Seiten: 403/404 → notFound(), sonst weiterwerfen */
export async function laden(fn) {
  try {
    return await fn();
  } catch (e) {
    if (e instanceof PlattformFehler && [403, 404].includes(e.status)) notFound();
    throw e;
  }
}
export function Karte({ titel, untertitel, aktion, children, className, innen = "p-5 md:p-6", as: Tag = "section", id }) {
  return (
    <Tag id={id} className={cn("min-w-0 rounded-3xl bg-white ring-1 ring-ink-200/70", className)}>
      {(titel || aktion) && (
        <div className="flex flex-wrap items-start justify-between gap-3 border-b border-ink-100 px-5 py-4 md:px-6">
          <div className="min-w-0">
            {titel && <h2 className="font-display text-[17px] font-bold text-ink-900">{titel}</h2>}
            {untertitel && <p className="mt-0.5 text-[13.5px] text-ink-500">{untertitel}</p>}
          </div>
          {aktion}
        </div>
      )}
      <div className={innen}>{children}</div>
    </Tag>
  );
}

/** Kopf einer Portalseite */
export function SeitenKopf({ eyebrow, titel, text, aktionen, children }) {
  return (
    <div className="mb-6 flex flex-col gap-4 md:mb-8 md:flex-row md:items-end md:justify-between">
      <div className="min-w-0">
        {eyebrow && <p className="text-[12px] font-semibold uppercase tracking-[0.16em] text-ov-700">{eyebrow}</p>}
        <h1 className="mt-1 font-display text-[26px] font-extrabold leading-tight tracking-tight text-ink-900 md:text-[32px]">{titel}</h1>
        {text && <p className="mt-2 max-w-2xl text-[15px] leading-relaxed text-ink-600">{text}</p>}
        {children}
      </div>
      {aktionen && <div className="flex shrink-0 flex-wrap gap-2">{aktionen}</div>}
    </div>
  );
}

/** Kennzahl-Kachel */
export function Leer({ icon: Icon, titel, text, aktion, className }) {
  return (
    <div className={cn("flex flex-col items-center rounded-3xl border border-dashed border-ink-200 bg-white/60 px-6 py-12 text-center", className)}>
      {Icon && (
        <span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-ov-50 text-ov-600">
          <Icon aria-hidden="true" className="h-6 w-6" />
        </span>
      )}
      <p className="mt-4 font-display text-[18px] font-bold text-ink-900">{titel}</p>
      {text && <p className="mt-1.5 max-w-md text-[14.5px] leading-relaxed text-ink-600">{text}</p>}
      {aktion && <div className="mt-5">{aktion}</div>}
    </div>
  );
}

/** Schlüssel-Wert-Liste */

