    rechtsform: "verein", zvrZahl: "999000417", firmenbuchnummer: "", sitzAdresse: { strasse: "Hauptplatz 1 (Demo)", plz: "4910", ort: "Ried im Innkreis" }, email: "sonnenland@example.com", telefon: "",
