  const P1 = [
    // [vorname, nachname/firma, art, konto, ZP: [richtung, kWp?, tf, status]]
    ["Mia", "Mitglied (Demo)", "privat", konten.mitglied, [["verbrauch", null, 100, "aktiv"]]],
