    if (a.eigentuemerMitgliedId && !x.mitglieder.some((m) => m.id === a.eigentuemerMitgliedId && m.gemeinschaftId === g.id)) throw ungueltig("Eigentümer muss Mitglied der Gemeinschaft sein.");
    if (alt) {
