      if (!nf || nf.id === g.id) throw ungueltig("Bitte die Nachfolger-Gemeinschaft angeben (Umwandlung = neue Gemeinschafts-ID).");
      g.nachfolgerId = nf.id;
      nf.vorgaengerId = g.id;
