    g.status = r.status;
    geaendert(g, n);
    protokoll(db, n, "eg_status", "eg_gemeinschaft", g.id, `Status ${GEMEINSCHAFT_STATUS[von]?.label || von} → ${GEMEINSCHAFT_STATUS[g.status].label}${grund ? ` (${String(grund).slice(0, 120)})` : ""}`);
