def runde_ct2(x):
	x = _num(x) or 0.0
	s = (x > 0) - (x < 0)
	return s * _js_round(abs(x) * 100 + 1e-9) / 100


def reduzierter_ap(ap_ct, reduktion_pct):
	return runde_ct2((_num(ap_ct) or 0) * (1 - (_num(reduktion_pct) or 0) / 100))


